// 1. Pega o conteúdo bruto da chave "data"
const rawData = $input.first().json.data;

if (!rawData) return [];

// 2. Separa por linhas e limpa linhas vazias
const lines = rawData.trim().split('\n');

// 3. Pega os cabeçalhos da primeira linha
const headers = lines[0].split(',').map(h => h.trim());

// 4. Converte as linhas de dados em Objetos
const results = lines.slice(1).map(line => {
    const values = [];
    let current = '';
    let inQuotes = false;

    // Lógica para separar por vírgula sem quebrar o que está entre aspas
    for (let char of line) {
        if (char === '"') {
            inQuotes = !inQuotes;
        } else if (char === ',' && !inQuotes) {
            values.push(current.trim());
            current = '';
        } else {
            current += char;
        }
    }
    values.push(current.trim());

    // Monta o objeto final baseando-se nos headers
    let obj = {};
    headers.forEach((header, index) => {
        let val = values[index] || "";

        // Remove aspas, limpa espaços e verifica se está vazio
        let cleanedVal = val.replace(/^"|"$/g, '').trim();

        // Se estiver vazio, coloca "null", caso contrário mantém o valor
        obj[header] = cleanedVal === "" ? "null" : cleanedVal;
    });

    return obj;
});

return results;

// 1. Pegamos as configurações do nó Webhook
const webhookBody = $("Webhook1").first().json.body;

const tagsParaExcluir = (webhookBody.etiquetas_excluir || []).map(t => t.toLowerCase().trim());
const tagsParaManter = (webhookBody.etiquetas_busca || []).map(t => t.toLowerCase().trim());
const manterTodasFlag = webhookBody.is_todas_etiquetas_selecionado;

// --- OTIMIZAÇÃO DE DATA ---
// Convertemos as datas do webhook para timestamp uma única vez
// Adicionamos "T00:00:00" para garantir que a comparação seja no fuso local
const timestampInicio = new Date(webhookBody.data_inicio + 'T00:00:00').getTime();
const timestampFim = new Date(webhookBody.data_fim + 'T23:59:59').getTime();

// 2. Filtramos a lista de itens
return $input.all().filter(item => {
  const lead = item.json;

  // --- REGRA 1: EXCLUSÃO (PRIORIDADE MÁXIMA) ---
  const rawEtiquetas = lead.Etiquetas || "";
  const etiquetasDoLead = rawEtiquetas.split(',')
    .map(tag => tag.trim().toLowerCase())
    .filter(tag => tag !== "");

  const possuiProibida = etiquetasDoLead.some(tag => tagsParaExcluir.includes(tag));
  if (possuiProibida) return false;

  // --- NOVA REGRA: FILTRO DE DATA ---
  // Formato do Lead: "22/04/2026" -> [22, 04, 2026]
  const partes = (lead.Data || "").split('/');
  if (partes.length === 3) {
    // Criamos a data do lead: ano, mês (0-11), dia
    const dataLead = new Date(partes[2], partes[1] - 1, partes[0]).getTime();

    // Se a data do lead estiver fora do intervalo, descarta
    if (dataLead < timestampInicio || dataLead > timestampFim) {
      return false;
    }
  }

  // --- REGRA 2: MANTER TODAS ---
  if (manterTodasFlag === true) return true;

  // --- REGRA 3: PERMANÊNCIA (LISTA DE BUSCA) ---
  const possuiTagDeBusca = etiquetasDoLead.some(tag => tagsParaManter.includes(tag));
  return possuiTagDeBusca;
});

